package main

import (
	"bufio"
	"fmt"
	"os"
)

func isLucky(x int64) bool {
	if x <= 0 {
		return false
	}
	for x > 0 {
		d := x % 10
		if d != 4 && d != 7 {
			return false
		}
		x /= 10
	}
	return true
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, k int64
	fmt.Fscan(reader, &n, &k)

	fact := make([]int64, 15)
	fact[0] = 1
	for i := 1; i <= 14; i++ {
		fact[i] = fact[i-1] * int64(i)
	}

	m := 0
	for m <= 14 && fact[m] < k {
		m++
	}
	if int64(m) > n {
		fmt.Println(-1)
		return
	}

	start := n - int64(m) + 1
	limit := start - 1

	// count lucky numbers <= limit
	var count int64 = 0
	var gen func(cur int64)
	gen = func(cur int64) {
		if cur > 0 {
			if cur <= limit {
				count++
			}
		}
		if cur > 2000000000 {
			return
		}
		if cur*10+4 <= 10000000000 {
			gen(cur*10 + 4)
			gen(cur*10 + 7)
		}
	}
	gen(0)

	nums := make([]int64, 0, m)
	for i := start; i <= n; i++ {
		nums = append(nums, i)
	}
	kk := k - 1
	for i := 0; i < m; i++ {
		f := fact[m-1-i]
		idx := kk / f
		kk %= f
		val := nums[idx]
		nums = append(nums[:idx], nums[idx+1:]...)
		pos := start + int64(i)
		if isLucky(pos) && isLucky(val) {
			count++
		}
	}

	fmt.Println(count)
}
